// Сюда приходят события ассистента.
// $json.body.type: transaction.created | transaction.updated | transaction.deleted |
//   transaction.group_deleted | meal.created | meal.updated | meal.deleted |
//   task.created | task.done | task.deleted
// $json.body.payload: данные записи

const ev = $json.body || {};

// Пример: отметить крупную трату (дальше можно отправить уведомление)
const big = ev.type === 'transaction.created' && ev.payload?.kind === 'expense'
  && Number(ev.payload?.amount) >= 10000;

return [{ json: { type: ev.type, big, payload: ev.payload } }];

// Собираем текст отчёта из списка операций
const rows = $input.all().map(i => i.json).filter(r => r.amount !== undefined);
const fmt = (v) => Math.round(v).toLocaleString('ru-RU') + ' ₽';
let exp = 0, inc = 0;
const byCat = {};
for (const r of rows) {
  const a = Number(r.amount);
  if (r.kind === 'income') { inc += a; continue; }
  exp += a;
  byCat[r.category] = (byCat[r.category] || 0) + a;
}
const top = Object.entries(byCat).sort((a, b) => b[1] - a[1])
  .map(([c, v]) => `• ${c}: ${fmt(v)}`).join('\n');
const text = `📅 <b>Итоги недели</b>\n\nРасходы: <b>${fmt(exp)}</b>\nДоходы: <b>${fmt(inc)}</b>\n\n${top || 'Трат не было 🎉'}`;
return [{ json: { text } }];
